import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.Pattern;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;

public class ReportServlet extends HttpServlet {
    private static final Pattern SAFE_ID = Pattern.compile("^[0-9a-f\\-]{36}$");

    // Connection pool configured via JNDI
    private Connection getConnection() throws Exception {
        javax.naming.Context ctx = new javax.naming.InitialContext();
        javax.sql.DataSource ds = (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/reportdb");
        return ds.getConnection();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String sortCol = req.getParameter("sort");

        // Validate report ID strictly
        if (reportId == null || !SAFE_ID.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Format whitelist - looks secure
        if (format == null) format = "json";
        if (!format.equals("json") && !format.equals("csv") && !format.equals("xml")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        // Sort column - developer assumed limited values but no validation
        if (sortCol == null) sortCol = "created_at";

        try (Connection conn = getConnection()) {
            // The reportId is safe (UUID validated), but sortCol is injected directly
            String query = "SELECT id, title, amount, created_at, status FROM reports "
                         + "WHERE tenant_id = (SELECT tenant_id FROM api_keys WHERE key_hash = ?) "
                         + "AND report_id = ? "
                         + "ORDER BY " + sortCol;

            PreparedStatement ps = conn.prepareStatement(query);
            ps.setString(1, hashApiKey(req.getHeader("X-API-Key")));
            ps.setString(2, reportId);

            ResultSet rs = ps.executeQuery();

            StringBuilder sb = new StringBuilder();
            if (format.equals("json")) {
                resp.setContentType("application/json");
                sb.append("[\n");
                boolean first = true;
                while (rs.next()) {
                    if (!first) sb.append(",\n");
                    sb.append(String.format(
                        "{\"id\":\"%s\",\"title\":\"%s\",\"amount\":%s,\"created_at\":\"%s\",\"status\":\"%s\"}",
                        rs.getString(1), escapeJson(rs.getString(2)),
                        rs.getBigDecimal(3), rs.getTimestamp(4), rs.getString(5)));
                    first = false;
                }
                sb.append("\n]");
            } else if (format.equals("csv")) {
                resp.setContentType("text/csv");
                sb.append("id,title,amount,created_at,status\n");
                while (rs.next()) {
                    sb.append(String.format("%s,%s,%s,%s,%s\n",
                        rs.getString(1), escapeCsv(rs.getString(2)),
                        rs.getBigDecimal(3), rs.getTimestamp(4), rs.getString(5)));
                }
            }

            resp.getWriter().write(sb.toString());
        } catch (SQLException e) {
            // Log full error for debugging - potential info leak
            resp.sendError(500, "Query failed: " + e.getMessage());
        } catch (Exception e) {
            resp.sendError(500, "Internal error");
        }
    }

    private String hashApiKey(String key) {
        try {
            java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(key.getBytes("UTF-8"));
            StringBuilder hex = new StringBuilder();
            for (byte b : hash) hex.append(String.format("%02x", b));
            return hex.toString();
        } catch (Exception e) {
            return "";
        }
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    private String escapeCsv(String s) {
        if (s == null) return "";
        if (s.contains(",") || s.contains("\"")) return "\"" + s.replace("\"", "\"\"") + "\"";
        return s;
    }
}

